import os, csv, json, statistics

dates = ["20191201", "20191202", "20191203"]
node_dir = os.environ["NODE_FLOW_DIR"]
station = "乌鲁木齐站"

daily = {}
read_ok = {}
for d in dates:
    path = os.path.join(node_dir, f"{d}_node.csv")
    try:
        s = 0.0
        with open(path, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                if row["站名"] == station:
                    v = row["计算流量"].strip()
                    if v:
                        s += float(v)
        daily[d] = s
        read_ok[d] = True
    except Exception:
        read_ok[d] = False
        daily[d] = None

demand = {d: (max(v, 0.0) if v is not None else None) for d, v in daily.items()}
vals = [v for v in demand.values() if v is not None]
mean = sum(vals) / len(vals)
mx, mn = max(vals), min(vals)
pstd = statistics.pstdev(vals)
z = {d: ((demand[d] - mean) / pstd if pstd > 0 else 0.0) for d in dates if demand[d] is not None}
anomalous = [d for d in dates if d in z and z[d] > 2]

out = {
    "station": station,
    "read_success": read_ok,
    "daily_sum_flow": daily,
    "daily_demand": demand,
    "mean": mean, "max": mx, "min": mn,
    "population_std": pstd,
    "z_scores": z,
    "anomalous_dates_z_gt_2": anomalous,
}
print(json.dumps(out, ensure_ascii=False, indent=2))

import os, csv, json, statistics
from decimal import Decimal

base = os.environ["NODE_FLOW_DIR"]
dates = ["20191205", "20191206", "20191207"]
daily = {}
read_ok = {}
for d in dates:
    fp = os.path.join(base, f"{d}_node.csv")
    try:
        total = Decimal("0")
        with open(fp, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                if row["站名"] == "上海站":
                    v = row["计算流量"].strip()
                    if v:
                        total += Decimal(v)
        daily[d] = total
        read_ok[d] = True
    except Exception:
        read_ok[d] = False
        daily[d] = None

demands = {d: (max(v, Decimal("0")) if v is not None else None) for d, v in daily.items()}
vals = [float(v) for v in demands.values() if v is not None]
mean = statistics.fmean(vals)
mx, mn = max(vals), min(vals)
std = statistics.pstdev(vals)
res = {
    "station": "上海站",
    "read_success": read_ok,
    "daily": {},
    "mean": round(mean, 3),
    "max": round(mx, 3),
    "min": round(mn, 3),
    "anomaly_dates": [],
}
for d in dates:
    if demands[d] is None:
        res["daily"][d] = {"demand": None, "z_score": None, "anomaly": None}
        continue
    fv = float(demands[d])
    z = (fv - mean) / std if std > 0 else 0.0
    anom = abs(z) > 2.5
    res["daily"][d] = {"demand": float(demands[d]), "z_score": round(z, 4), "anomaly": anom}
    if anom:
        res["anomaly_dates"].append(d)
print(json.dumps(res, ensure_ascii=False, default=str))

