seg_flows = {}

for d in DATES:
    npath = os.path.join(NODE_DIR, d + "_node.csv")
    ppath = os.path.join(PIPE_DIR, d + "_pipeline.csv")
    try:
        supply = 0.0
        demand = 0.0
        with open(npath, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                if row["管道划分"] != TARGET:
                    continue
                v = row["计算流量"]
                if v is None or v == "":
                    continue
                v = float(v)
                if row["类型"] == "气源":
                    supply += abs(v)
                elif row["类型"] == "需求":
                    demand += abs(v)
        daily[d] = {"supply": round(supply, 3), "demand": round(demand, 3), "gap": round(supply - demand, 3)}
    except Exception as e:
        failed.append({"date": d, "file": "node", "error": str(e)})
    try:
        with open(ppath, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                if row["管道划分"] != TARGET:
                    continue
                key = (row["起点站名"], row["终点站名"])
                seg_flows.setdefault(key, []).append(abs(float(row["管道流量"])))
    except Exception as e:
        failed.append({"date": d, "file": "pipeline", "error": str(e)})

def p95(vals):
    s = sorted(vals)
    n = len(s)
    if n == 1:
        return s[0]
    k = (n - 1) * 0.95
    lo = int(k)
    hi = min(lo + 1, n - 1)
    frac = k - lo
    return s[lo] + (s[hi] - s[lo]) * frac

segs = []
for key, vals in seg_flows.items():
    segs.append({
        "segment": key[0] + "->" + key[1],
        "mean_abs_flow": round(statistics.fmean(vals), 3),
        "p95_abs_flow": round(p95(vals), 3),
        "max_abs_flow": round(max(vals), 3),
        "days": len(vals),
    })
segs.sort(key=lambda x: x["mean_abs_flow"], reverse=True)

worst = min(daily.items(), key=lambda kv: kv[1]["gap"]) if daily else None

out = {
