    "daily_summary": daily,
    "worst_gap_day": ({"date": worst[0], **worst[1]} if worst else None),
    "top8_segments_by_mean_abs_flow": segs[:8],
    "read_failures": failed,
}
print(json.dumps(out, ensure_ascii=False, indent=2))

