from collections import deque

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / "20190114_pipeline.csv"

adj = {}
with open(csv_path, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        s, t, p = row["source"], row["target"], row["pipeline"]
        adj.setdefault(s, []).append((t, p))
        adj.setdefault(t, []).append((s, p))  # undirected for reachability path

def bfs(src, dst):
    q = deque([(src, [])])
