with open(NDIR / f"{date}_node.csv", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        for k, v in row.items():
            if v and ("站" in v or "首站" in v):
                nodes.add(v.strip())

adj = {}
with open(PDIR / f"{date}_pipeline.csv", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        keys = list(row.keys())
        vals = list(row.values())
        # find source/target/pipeline columns heuristically
        src = tgt = pipe = None
        for k, v in row.items():
            kl = k.lower()
            if src is None and ("source" in kl or "起点" in k):
                src = v.strip()
            elif tgt is None and ("target" in kl or "终点" in k):
                tgt = v.strip()
            elif pipe is None and ("pipeline" in kl or "管道" in k or "管线" in k):
                pipe = v.strip()
        if src and tgt:
            adj.setdefault(src, []).append((tgt, pipe))
            adj.setdefault(tgt, []).append((src, pipe))

def bfs(start, goal):
    q = deque([(start, [])])
    seen = {start}
    while q:
        cur, path = q.popleft()
        if cur == goal:
            return path
        for nxt, pipe in adj.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, path + [{"source": cur, "target": nxt, "pipeline": pipe}]))
    return None

res = {}
for s in ["榆林站"]:
    res[s] = bfs(s, "如皋站")
print(json.dumps(res, ensure_ascii=False, default=str))

