import os, csv, json
from pathlib import Path
from collections import deque

date = "20190114"
DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / f"{date}_pipeline.csv"

adj = {}
with open(csv_path, encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        s, t, p = row["起点站名"], row["终点站名"], row["管道划分"]
        adj.setdefault(s, []).append((t, p))
        adj.setdefault(t, []).append((s, p))

target = "宝坻站"
sources = ["榆林站", "黑河首站"]

def bfs(src):
    prev = {src: None}
    q = deque([src])
    while q:
        u = q.popleft()
        if u == target:
            break
        for v, p in adj.get(u, []):
            if v not in prev:
                prev[v] = (u, p)
                q.append(v)
    if target not in prev:
        return None
    path = []
    cur = target
    while prev[cur] is not None:
        u, p = prev[cur]
        path.append({"source": u, "target": cur, "pipeline": p})
        cur = u
    path.reverse()
    return path

out = {}
for s in sources:
    path = bfs(s)
    out[s] = {"hops": len(path) if path else None, "path": path}

print(json.dumps(out, ensure_ascii=False, indent=1))

